parameters.jsonBody:
={{ JSON.stringify({
  model: "gpt-4o-mini",
  response_format: { type: "json_object" },
  messages: [
    {
      role: "system",
      content: "You are a property maintenance request classifier. Given a tenant's issue description, respond with JSON only, no other text: {\"category\": \"Plumbing\" or \"Electrical\" or \"General\", \"urgency\": \"Emergency\" or \"Routine\"}. Emergency means flooding, no heat, no water, gas smell, fire risk, or an active electrical hazard. Everything else is Routine."
    },
    {
      role: "user",
      content: $json.fields.Description || ""
    }
  ]
}) }}

parameters.jsCode:
let parsed;
try {
  parsed = JSON.parse($json.choices[0].message.content);
} catch (e) {
  parsed = { category: 'General', urgency: 'Routine' };
}

return {
  category: parsed.category || 'General',
  urgency: parsed.urgency || 'Routine'
};
